export function robotOffer(state,model){
 const def=typeof model==='string'?state.catalog.find(r=>r.id===model):model;
 if(!def)throw new Error('Modelo não encontrado.');
 const {lcPerReal,rcPerLC}=state.settings;
 if(!Number.isFinite(lcPerReal)||lcPerReal<=0||!Number.isFinite(rcPerLC)||rcPerLC<=0)throw new Error('Cotação inválida.');
 const dailyRC=Math.floor(def.daily*(state.settings.productionMultiplier??1)),totalRC=dailyRC*def.lifetime,rcToBRL=1/rcPerLC/lcPerReal;
 return {dailyRC,totalRC,dailyLC:dailyRC/rcPerLC,totalLC:totalRC/rcPerLC,dailyBRL:dailyRC*rcToBRL,totalBRL:totalRC*rcToBRL,priceBRL:def.currency==='RC'?def.price*rcToBRL:def.price/lcPerReal,principalReturnLC:Math.floor((def.currency==='LC'?def.price:Math.floor(def.price/rcPerLC))*(state.settings.principalReturnPercent??100)/100),days:def.lifetime,lcPerReal,rcPerLC};
}
export const approximateBRL=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:value>0&&value<.01?4:2}).format(value);
export function createRobotOfferView(env){
 const {escape:esc,sprite,coin,button:btn,icon:I,format:n}=env;
 function projection(model,compact=false){const q=robotOffer(env.getState(),model);return `<div class="robot-yield ${compact?'compact':''}"><div class="yield-daily">${coin('RC')}<span><small>GERAÇÃO POR DIA</small><b>${n(q.dailyRC)} RC <em>/ dia</em></b><strong>≈ ${approximateBRL(q.dailyBRL)} / dia</strong></span></div><div class="yield-lifetime"><span>Estimativa em ${q.days} dias</span><b>${n(q.totalRC)} RC</b><small>≈ ${approximateBRL(q.totalBRL)} na cotação atual</small></div></div>`;}
 function open(id){const state=env.getState(),r=state.catalog.find(x=>x.id===id);if(!r)return;const q=robotOffer(state,r),className={explorer:'Explorador',striker:'Atacante',guardian:'Guardião'}[r.type]||r.type;
  env.modal(`<div class="acquisition-hero" style="--robot-color:${r.color}"><div class="acquisition-rings"></div>${sprite(r,'acquisition-sprite')}<span class="rarity ${r.rarity.toLowerCase()}">${esc(r.rarity)}</span></div><div class="acquisition-heading"><span class="eyebrow">${esc(className)} · NÍVEL INICIAL 1</span><h2 id="modal-title">${esc(r.name)}</h2><p>Um novo companheiro para sua próxima missão.</p></div><p class="acquisition-story">${esc(r.description)}</p>${projection(r)}<div class="acquisition-stats"><span>${I('arena')}<b>${r.attack}</b><small>Ataque</small></span><span>${I('shield')}<b>${r.defense}</b><small>Defesa</small></span><span>${I('bolt')}<b>${r.health}</b><small>Vida</small></span><span>${I('clock')}<b>${r.lifetime} dias</b><small>Prazo</small></span></div><div class="acquisition-contract"><span>${I('robot')} ${r.maxBattles} usos na arena durante a vida do robô</span><span>${I('core')} Peças e níveis podem ampliar produção e atributos</span></div><div class="acquisition-price"><span>Aquisição</span><b>${coin(r.currency)} ${n(r.price)} ${r.currency}</b><small>≈ ${approximateBRL(q.priceBRL)} de equivalente</small></div><div class="acquisition-return">${coin('LC')}<div><b>${n(q.principalReturnLC)} LC voltam à carteira ao expirar</b><small>${state.settings.principalReturnPercent??100}% do valor de aquisição · regra congelada na compra. Equipamentos e evoluções não entram nesta devolução.</small></div></div><div class="offer-exchange"><span>R$ 1 = ${n(q.lcPerReal)} LC</span><span>${n(q.rcPerLC)} RC = 1 LC</span></div><p class="acquisition-note">Estimativa do robô no nível 1, sem equipamentos. O equivalente em reais acompanha a cotação do jogo e pode variar.</p><div class="modal-actions">${btn('Confirmar aquisição '+I('plus'),'buy-robot-confirm',`data-id="${esc(r.id)}"`)}${btn('Voltar à oficina','close','','secondary')}</div>`,'acquisition-modal');
 }
 return {open,projection};
}
